#!/usr/bin/env bash
# Verifies the deployed contracts on the Etherscan explorers: etherscan.io, bscscan.com, basescan.org, arbiscan.io.
# Needs ETHERSCAN_API_KEY in the environment or in .env (one free key covers all four).
set -uo pipefail
cd "$(dirname "$0")/.."
key="${ETHERSCAN_API_KEY:-$(sed -n 's/^ETHERSCAN_API_KEY=//p' .env 2>/dev/null | tr -d '"')}"
[ -n "$key" ] || { echo "Put ETHERSCAN_API_KEY=... in bulmo-multisend-contracts/.env first."; exit 1; }
export ETHERSCAN_API_KEY="$key"

multisend_
factory_args=00000000000000000000000008203722853612c1c828f02367725b23449c8d8000000000000000000000000000000000000000000000000000000002540be40000000000000000000000000000000000000000000000000000000001241011000000000000000000000000000000000000000000000000008ac7230489e80000

failed=0
verify() { # chain address contract [constructor args]
  echo "== chain $1: $3"
  forge verify-contract "$2" "src/$3.sol:$3" --chain "$1" --verifier etherscan --watch ${4:+--constructor-args "$4"} 2>&1 | tail -3
  [ "${PIPESTATUS[0]}" -eq 0 ] || failed=1
  sleep 1
}
for chain in ${CHAINS:-1 56 8453 42161}; do
  verify "$chain" 0xEF37b4902AD3eDc923112BD47C0D776bd2A419B3 BulmoMultisend "$multisend_args"
  verify "$chain" 0xC90079E3C00671B13a8f85d2FC2c9E9A0F3305D9 BulmoMultisendFactory "$factory_args"
  verify "$chain" 0xFd5602187ce9Cd6c53C8469BBB518eBe913b2896 BulmoPersonalMultisend
done
exit $failed
